func (m *MatchRemoteIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	d.Next() // consume matcher name
	matcherName := d.Val()
	namedMatcher := d.GetContextString(caddyfile.MatcherNameCtxKey)
	for d.NextArg() {
		tok := d.Token()
		val := tok.Text
		msg := ""
		if matcherName == "remote_ip" && val == "forwarded" {
			msg = "the 'forwarded' option is no longer supported; use the 'client_ip' matcher instead"
		}
		if msg != "" {
			if namedMatcher != "" {
				msg += " in matcher '" + namedMatcher + "'"
			}
			if tok.Quoted() {
				msg += " (quoted)"
			}
			if chain := tok.ImportChain(); len(chain) > 0 {
				return fmt.Errorf("%s, at %s:%d import chain ['%s']", msg, tok.File, tok.Line, strings.Join(chain, "','"))
			}
			return fmt.Errorf("%s, at %s:%d", msg, tok.File, tok.Line)
		}
		if val == "private_ranges" {
			m.Ranges = append(m.Ranges, PrivateRangesCIDR()...)
			continue
		}
		m.Ranges = append(m.Ranges, val)
	}
	if d.NextBlock(d.Nesting()) {
		tok := d.Token()
		msg := "malformed " + matcherName + " matcher: blocks are not supported"
		if namedMatcher != "" {
			msg += " in matcher '" + namedMatcher + "'"
		}
		if tok.Quoted() {
			msg += " (quoted)"
		}
		if chain := tok.ImportChain(); len(chain) > 0 {
			return fmt.Errorf("%s, at %s:%d import chain ['%s']", msg, tok.File, tok.Line, strings.Join(chain, "','"))
		}
		return fmt.Errorf("%s, at %s:%d", msg, tok.File, tok.Line)
	}

