package main

import (
	"context"
	"fmt"
	"net/http"

	"github.com/caddyserver/caddy/v2"
	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
	"github.com/caddyserver/caddy/v2/modules/caddyhttp"
	_ "github.com/caddyserver/caddy/v2/caddyhttp/standard"
)

func main() {
	caddyfileInput := `{
	admin off
}
:8080 {
	@webhook {
		path "/webhook"
		not {
			client_ip 51.138.37.238 20.54.89.16
			client_ip 20.50.240.57 1.2.3.4
			client_ip 10.0.0.1
		}
	}
	handle @webhook {
		abort
	}
	respond "allowed"
}
`
	var cfgAdapter caddyfile.Adapter
	serverType := "http"
	adapter := caddyfile.Adapter{ServerType: serverType}
	cfgAdapter = adapter
	adaptedConfig, warnings, err := cfgAdapter.Adapt([]byte(caddyfileInput), nil)
	if err != nil {
		panic(err)
	}
	_ = warnings

	var cfg *caddy.Config
	if err = caddy.StrictUnmarshalJSON(adaptedConfig, &cfg); err != nil {
		panic(err)
	}

	// find the not matcher
	var notMatcher *caddyhttp.MatchNot
	for _, route := range cfg.AppsRaw["http"] /* unused */ {
		_ = route
		break
	}
	_ = notMatcher

	// Instead, unmarshal the matcher directly from the adapted JSON via module loading is complex;
	// simpler: parse the not block tokens directly.
	// Parse the matcher token from the Caddyfile.
	tokens := []caddyfile.Token(nil)

	d := caddyfile.NewDispenser(tokens)
	_ = d

	// Fallback: exercise MatchClientIP merging directly via UnmarshalCaddyfile
	input := `client_ip 51.138.37.238 20.54.89.16
client_ip 20.50.240.57 1.2.3.4
client_ip 10.0.0.1`
	toks, err := allTokens(input)
	if err != nil {
		panic(err)
	}
	disp := caddyfile.NewDispenser(toks)
	m := &caddyhttp.MatchClientIP{}
	if err := m.UnmarshalCaddyfile(disp); err != nil {
		panic(err)
	}
	err = m.Provision(caddy.Context{Context: context.Background()})
	if err != nil {
		panic(err)
	}
	fmt.Println("ranges:", m.Ranges)
	fmt.Println("num cidrs:", len(m.Ranges))

	for _, ip := range []string{"51.138.37.238", "1.2.3.4", "10.0.0.1", "9.9.9.9"} {
		r, _ := http.NewRequest("GET", "/", nil)
		ctx := caddyhttp.WithReplacer(r.Context(), caddy.NewReplacer())
		r = r.WithContext(ctx)
		caddyhttp.SetVar(r.Context(), "client_ip", ip)
		fmt.Printf("client_ip %s match: %v\n", ip, m.Match(r))
	}
}

func allTokens(input string) ([]caddyfile.Token, error) {
	return caddyfile.AllTokens([]byte(input))
}

