package main

import (
	"context"
	"fmt"
	"net/http"

	"github.com/caddyserver/caddy/v2"
	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
	"github.com/caddyserver/caddy/v2/modules/caddyhttp"
)

func main() {
	input := `client_ip 51.138.37.238 20.54.89.16
client_ip 20.50.240.57 1.2.3.4
client_ip 10.0.0.1`
	toks, err := caddyfile.Tokenize([]byte(input), "Caddyfile")
	if err != nil {
		panic(err)
	}
	disp := caddyfile.NewDispenser(toks)
	m := &caddyhttp.MatchClientIP{}
	if err := m.UnmarshalCaddyfile(disp); err != nil {
		panic(err)
	}
	if err := m.Provision(caddy.Context{Context: context.Background()}); err != nil {
		panic(err)
	}
	fmt.Println("client_ip ranges:", m.Ranges)

	for _, ip := range []string{"51.138.37.238", "1.2.3.4", "10.0.0.1", "9.9.9.9"} {
		r, _ := http.NewRequest("GET", "/", nil)
		ctx := context.WithValue(r.Context(), caddy.ReplacerCtxKey, caddy.NewReplacer())
		r = r.WithContext(ctx)
		caddyhttp.SetVar(r.Context(), "client_ip", ip)
		fmt.Printf("client_ip %s match: %v\n", ip, m.Match(r))
	}

	toks2, _ := caddyfile.Tokenize([]byte("remote_ip 1.1.1.1\nremote_ip 2.2.2.2"), "Caddyfile")
	disp2 := caddyfile.NewDispenser(toks2)
	m2 := &caddyhttp.MatchRemoteIP{}
	if err := m2.UnmarshalCaddyfile(disp2); err != nil {
		panic(err)
	}
	if err := m2.Provision(caddy.Context{Context: context.Background()}); err != nil {
		panic(err)
	}
	fmt.Println("remote_ip ranges:", m2.Ranges)
}

